CREATE TABLE account_consent_contexts(
    account_id INTEGER PRIMARY KEY REFERENCES accounts(id),
    context_id TEXT NOT NULL UNIQUE REFERENCES consultation_consent_contexts(id)
);

INSERT INTO consent_documents(purpose,version,title,body,retention,created_at) VALUES
('audio_recording','account-local-v3-2026-10-22','Аудиозаписи встреч',
 'Разрешаю ведущему врачу загружать и хранить аудиозаписи моих встреч в локальном Клиническом компасе. Выбор действует для моих встреч до изменения в настройках; повторное подтверждение каждой встречи не требуется. Само разрешение не запускает запись. Видеозаписи, расшифровка и итоги включаются отдельно.',
 'Новые файлы хранятся 30 дней после загрузки. Отключение запрещает новую загрузку и дальнейшую обработку соответствующих записей, но не удаляет историю автоматически. Удаление файла и производных доступно отдельно; резервными копиями управляет владелец сервера.', '2026-10-22T00:00:00Z'),
('video_recording','account-local-v3-2026-10-22','Видеозаписи встреч',
 'Разрешаю ведущему врачу загружать и хранить видеозаписи моих встреч со звуком в локальном Клиническом компасе. Выбор действует до изменения в настройках для моих встреч, без повторных подтверждений. Камера автоматически не включается. Расшифровка и итоги включаются отдельно.',
 'Новые файлы хранятся 30 дней после загрузки. Отключение запрещает новую загрузку и дальнейшую обработку соответствующих записей; ранее сохранённые сведения и история автоматически не удаляются. Доступны отдельное удаление файла и производных; резервные копии обслуживаются отдельно.', '2026-10-22T00:00:00Z'),
('ai_transcription','account-local-v3-2026-10-22','Расшифровка записей',
 'Разрешаю ведущему врачу запускать локальное распознавание разрешённых записей моих встреч. Записи не отправляются внешнему ИИ; исходный файл и машинный текст сохраняются отдельно. Выбор действует до изменения в настройках для моих встреч. Врач проверяет ошибки. Создание итогов разрешается отдельно.',
 'Тексты доступны до истечения срока хранения исходной записи. Отключение запрещает новые запуски; результат уже начатой обработки после изменения разрешения не сохраняется. Сохранённые тексты и история автоматически не удаляются; удаление файла очищает его производные.', '2026-10-22T00:00:00Z'),
('ai_summary','account-local-v3-2026-10-22','Итоги и следующие шаги',
 'Разрешаю ведущему врачу создавать локальный черновик итогов и обсуждённых следующих шагов по разрешённой расшифровке моих встреч. Выбор действует до изменения в настройках для моих встреч. Врач проверяет смысл, лекарства и источники, затем отдельно публикует результат. ИИ не назначает и не отменяет лечение.',
 'Срок связан с исходной записью. Отключение запрещает новые запуски; результат уже начатой обработки после изменения разрешения не сохраняется. Опубликованные врачом сведения и история не удаляются автоматически; производные можно удалить с записью.', '2026-10-22T00:00:00Z');
